import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:booking/theme/app_theme.dart';
import 'package:booking/screens/admin/admin_auth_gate.dart';
import 'package:booking/data/mock_data.dart';
import 'package:booking/firebase_options.dart';

// ⚠️  firebase_options.dart is generated by FlutterFire CLI.
// Run: dart pub global activate flutterfire_cli
//      flutterfire configure
// Then un-comment the import below and remove this comment.

// ============================================================
// Admin Entry Point — Movix Admin Web App
// Deployed to Netlify as a Flutter web build:
//   flutter build web -t lib/main_admin.dart
//
// Security model:
//   Layer 0: Netlify URL is publicly reachable (hosting-level restriction
//            requires a paid Netlify feature or reverse proxy — not implemented)
//   Layer 1: AdminAuthGate checks Firebase session + Firestore admin role
//   Layer 2: Firestore Security Rules enforce access at the data layer
// ============================================================

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  } catch (e) {
    runApp(_FirebaseErrorApp(message: e.toString()));
    return;
  }

  await MockData.loadData();
  runApp(const AdminApp());
}

class AdminApp extends StatelessWidget {
  const AdminApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Movix Admin',
      debugShowCheckedModeBanner: false,
      theme: AppTheme.lightTheme,
      // AdminAuthGate replaces the direct AdminDashboard() to add the auth gate.
      // AdminDashboard UI, theme, and functionality are completely unchanged.
      home: const AdminAuthGate(),
    );
  }
}

// ── Firebase init error screen ────────────────────────────────────────────────
class _FirebaseErrorApp extends StatelessWidget {
  final String message;
  const _FirebaseErrorApp({required this.message});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: Scaffold(
        backgroundColor: Colors.white,
        body: Center(
          child: Padding(
            padding: const EdgeInsets.all(32),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Icon(Icons.warning_amber_rounded,
                    color: AppTheme.primaryRed, size: 56),
                const SizedBox(height: 24),
                const Text(
                  'Firebase Initialisation Failed',
                  style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                    color: AppTheme.textPrimary,
                  ),
                  textAlign: TextAlign.center,
                ),
                const SizedBox(height: 12),
                const Text(
                  'Run `flutterfire configure` and ensure the Web app '
                  'is registered in Firebase Console.',
                  style: TextStyle(
                    color: AppTheme.textSecondary,
                    fontSize: 13,
                    height: 1.5,
                  ),
                  textAlign: TextAlign.center,
                ),
                const SizedBox(height: 20),
                Text(
                  message,
                  style: const TextStyle(color: Colors.red, fontSize: 11),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}